script:
frappe.ui.form.on('Coupon Code', {

    setup(frm) {

        frm.set_query('custom_employee', function() {

            return {
                filters: {
                    department: frm.doc.custom_department
                }
            };

        });

    },

    custom_department: function(frm) {
        // reset employee when department changes
        frm.set_value('custom_employee', null);
    }

});
